"""Pin the comment header of the generated validate requirements file."""

from __future__ import annotations

import re
from itertools import takewhile
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[2]
REQUIREMENTS = ROOT / "tests" / "validate" / "requirements.txt"

EXPECTED_HEADER = (
    "# This file was autogenerated by uv via the following command:",
    (
        "#    uv pip compile tests/validate/requirements.in --generate-hashes"
        " --python-version 3.14 -o tests/validate/requirements.txt"
    ),
)


def leading_comments(text: str) -> tuple[str, ...]:
    """Return the lines before the first line that is not a comment."""
    return tuple(takewhile(lambda line: line.startswith("#"), text.splitlines()))


def check_header(text: str) -> None:
    """Raise AssertionError, showing both, unless the header is EXPECTED_HEADER."""
    actual = leading_comments(text)

    assert actual == EXPECTED_HEADER, (
        "expected header:\n"
        + "\n".join(EXPECTED_HEADER)
        + "\nactual header:\n"
        + "\n".join(actual)
    )


def test_requirements_header_is_the_expected_literal() -> None:
    """Fail when the header is anything but EXPECTED_HEADER.

    uv records the compile command in the header, and run with absolute
    arguments it writes the generating machine's paths into the file.
    This test does not judge paths; it only forces a look.  When the
    compile command changes on purpose, update EXPECTED_HEADER with it.
    """
    check_header(REQUIREMENTS.read_text())


def test_a_header_changed_without_a_path_no_longer_matches() -> None:
    changed = re.sub(
        r"--python-version \S+", "--python-version 0.0", EXPECTED_HEADER[1]
    )
    assert changed != EXPECTED_HEADER[1], (
        "EXPECTED_HEADER lost its --python-version flag"
    )
    text = "\n".join((EXPECTED_HEADER[0], changed, "gherkin-official==1.0 \\"))

    assert leading_comments(text) == (EXPECTED_HEADER[0], changed)
    with pytest.raises(AssertionError):
        check_header(text)
